import {snapshotBrief,briefHash,dimensions} from '../../src/bhs/brief.mjs';
import {methodologyAreas} from '../../src/bhs/methodology-areas.mjs';
import {hash} from '../../src/budget/ledger.mjs';
export const brief=snapshotBrief({brandName:'Acme Organic',website:'https://acme.example/',segment:'kobi',goals:'Türkiye pazarında sürdürülebilir büyüme.',needs:'Darboğazların kaynaklı değerlendirmesi.',services:'SEO ve reklam danışmanlığı',meetingNotes:'Kamuya açık sentetik test; gerçek müşteri verisi yok.'});
const brandText=[
 'Acme Organic, organik yulaf ve meyve atıştırmalıkları üreten bir markadır. Ürünler web mağazasında doğrudan tüketiciye satılır.',
 'Acme Organic Türkiye pazarına satış yapar. Marka Acme Gıda şirketine bağlıdır. Şirketin kamuya açıkladığı ekip büyüklüğü 10 çalışandır.',
 'Acme Organic organik yulaf barı ürününün web mağazasındaki listelenen fiyatı 100 TL olarak gösterilir. Ciro ve katkı kârı kamuya açıklanmamıştır.',
 'Acme Organic web mağazasında 500 TL üzerindeki alışverişler için ücretsiz kargo sunar. Belirtilen teslimat süresi 3 iş günüdür.',
 'Acme Organic müşterileri e-posta bültenine kaydolabilir. Ürün sayfasında sepete ekleme ve içerik açıklaması görünür; gerçek dönüşüm oranı paylaşılmaz.',
 'Acme Organic sitesinde müşteri yorumları ve marka yanıtları yayımlanır. Bir müşteri teslimat gecikmesini bildirmiş, marka destekle iletişime geçmesini istemiştir.',
 'Acme Organic ürün sayfasında başlık ve açıklama meta verileri bulunur. Statik HTML sinyali hız, mobil deneyim veya etiketlerin çalışırlığını ölçmez.'
];
const sectorText=[
 'Türkiye organik atıştırmalık sektöründe gelir ürün satışıyla oluşur. Ürün başına fiyat, tekrar satın alma ve dağıtım kanalları satışları etkileyen değişkenlerdir.',
 'Organik atıştırmalık müşterileri içerik açıklaması, sertifika kapsamı, birim fiyat ve teslimat koşullarını karşılaştırır. Bu sektör bağlamı tek bir markanın müşterilerinin tamamını temsil etmez.',
 'Organik atıştırmalık pazarında hammadde maliyetleri ve yerel ürün rekabeti risk oluşturabilir. Gözlenen sektör koşulları Acme Organic şirketinin gerçekleşmiş kârını göstermez.'
];
export const plan={entities:[{id:'brand',role:'brand',name:brief.brandName,website:brief.website,scaleReason:'Açıklanan ekip.',audienceReason:'Organik atıştırmalık alıcıları.',geographyReason:'Türkiye.',scope:'Organic snack products.'},...['Alpha','Beta','Gamma'].map((name,i)=>({id:'peer'+i,role:'competitor',name:'Organic '+name,website:'https://peer'+i+'.example/',scaleReason:'Ölçek eşitliği bilinmiyor.',audienceReason:'Organic snack buyers in Türkiye.',geographyReason:'Türkiye pazarında satış.',scope:'Organic oat snack bars in Türkiye.'}))],sources:[{url:brief.website,purpose:'Marka.'},...[0,1,2].map(i=>({url:'https://peer'+i+'.example/',purpose:'Resmî rakip ürün sayfası.'}))]};
const source=(id,url,title,texts)=>({id,url,finalUrl:url,title,method:'html',retrievedAt:'2026-11-10T00:00:00Z',contentHash:hash(texts),excerpts:texts.map(text=>({text})),...(id==='ev1'?{technicalSignals:{navigation:[{url:'https://www.instagram.com/acmeorganic/'},{url:'https://www.linkedin.com/company/acme-organic/'}],https:true}}:{})});
export const packet=()=>({version:'sellf-evidence-v1',briefHash:briefHash(brief),asOf:'2026-11-10',entities:plan.entities,sources:[source('ev1',brief.website,'Acme Organic',brandText),source('ev2','https://industry.example/report','Türkiye organik atıştırmalık raporu',sectorText),...[0,1,2].map(i=>source('ev'+(i+3),'https://peer'+i+'.example/','Organic '+['Alpha','Beta','Gamma'][i],[`Organic ${['Alpha','Beta','Gamma'][i]} Türkiye'de organik yulaf atıştırmalık barları satmaktadır. Web mağazasında ürün içerikleri ve teslimat koşulları açıklanır.`,`Organic ${['Alpha','Beta','Gamma'][i]} için listelenen ürün fiyatı ${110+i*10} TL'dir. Bu bilgi aynı gramaj, paket ve kargo koşullarında karşılaştırılmalıdır.`]))],unavailable:[]});
export function fakeCollector(){return async(_brief,p,options={})=>{const all=packet(),entities=p.entities;const includePeers=entities.some(e=>e.role==='competitor');return {...all,entities,sources:all.sources.filter(s=>includePeers||!s.url.includes('peer')).slice(0,options.sourceLimit||24)};};}
const sections=input=>input.sources.flatMap(s=>s.sections.map(p=>({url:s.url,text:p.text,id:p.proofIds[0]}))).filter(p=>p.text);
function section(input,pattern){const all=sections(input),p=all.find(s=>pattern.test(s.text));if(!p)throw Error('Fixture source missing '+pattern);return p;}
function fact(input,id,topic,pattern){const p=section(input,pattern);return {id,kind:'observation',topic,statement:p.text,sourceIds:[p.id],limitation:'Kamuya açık kaynak kapsamıyla sınırlı; ticari sonuç ölçülmedi.'};}
function finding(input,id,dimension,pattern,quadrant='strength'){
 const p=section(input,pattern);return {id,dimension,kind:['opportunity','threat'].includes(quadrant)?'inference':'observation',stance:quadrant==='strength'?'positive':quadrant==='weakness'||quadrant==='threat'?'risk':'neutral',observation:p.text,sourceIds:[p.id],commercialHypothesis:'Bu gözlemin satın alma kararına ve operasyon maliyetine etkisi iç verilerle değerlendirilebilir.',limitation:'Kaynak kapsamı sınırlı; gerçekleşmiş ticari etki ölçülmedi.',question:'Bu gözlemin iş sonuçlarına etkisini hangi güncel verilerle değerlendiriyorsunuz?',priority:'high',quadrant};
}
export function modelAnswer(stage,input){
 if(stage.endsWith('-repair-extract'))return modelAnswer(stage.replace('-repair-extract','-extract').replace('v8-swot-extract','v8-swot-draft'),input);
 if(stage==='v8-brand-plan')return {instruction:'Markanın ürününü, iş modelini ve pazarını kaynakla açıkla; sahipliği ve ölçeği doğrula.',queries:['Acme Organic products market','Acme Organic ownership team']};
 if(stage==='v8-brand-extract')return {facts:[fact(input,'identity','identity',/üreten bir markadır/),fact(input,'products','products',/üreten bir markadır/),fact(input,'business_model','business_model',/doğrudan tüketiciye/),fact(input,'market','market',/Türkiye pazarına/),fact(input,'scale','scale',/ekip büyüklüğü/),fact(input,'ownership','ownership',/şirketine bağlıdır/)],unknowns:['Gerçekleşmiş ciro kamuya açıklanmadı.']};
 if(stage==='v8-sector-extract')return {facts:[fact(input,'sector','sector',/sektöründe gelir/),fact(input,'revenue','revenue_drivers',/sektöründe gelir/),fact(input,'behavior','customer_behavior',/müşterileri içerik açıklaması/),fact(input,'risk','market_risk',/hammadde maliyetleri/)],unknowns:[]};
 if(stage==='v8-sector-validation')return {facts:input.candidates.map(f=>({...f,kind:'observation'})),unknowns:[],decision:'accepted',notes:'Kaynaklı iş modeli sınıflandırıldı.',nextTask:{instruction:'Doğrudan rakipleri araştır.',queries:['organic snack product brand competitors Türkiye']}};
 if(stage==='v8-peer-candidates')return plan;
 if(stage==='v8-competition-extract')return {facts:[0,1,2].map(i=>fact(input,'peer-fact'+i,'product_overlap',new RegExp('Organic '+['Alpha','Beta','Gamma'][i]+" Türkiye'de"))),unknowns:['Ölçek eşitliği doğrulanmadı.']};
 if(stage==='v8-swot-draft')return {findings:[finding(input,'w1','funnel',/e-posta bültenine/,'strength'),finding(input,'w2','perception',/teslimat gecikmesini/,'weakness'),finding(input,'w3','financial',/tekrar satın alma/,'opportunity'),finding(input,'w4','competition',/hammadde maliyetleri/,'threat')],unknowns:['Özel finansal metrikler bilinmiyor.']};
 if(stage.includes('-review')){
  const next=stage.includes('brand')?{instruction:'Sektörün gelir dinamiklerini ve müşterinin satın alma davranışını araştır.',queries:['Türkiye organic snack market customer behavior','Türkiye organic snack industry sales conditions']}:stage.includes('sector')?{instruction:'Aynı ürün ve pazarda doğrudan rakipleri karşılaştır.',queries:['Acme organic bar competitors Türkiye','organic oat bar alternatives Türkiye']}:stage.includes('competition')?{instruction:'Markanın yorumlarını, şikâyetlerini ve geçmişini araştır; kaynaklı SWOT taslağı çıkar.',queries:['Acme Organic reviews complaints history','Acme Organic company news']}: {instruction:'Bulguları 24 BHS alanına grupla ve kritik veri açıklarını belirle.',queries:[]};
  return {acceptedIds:input.candidates.map(f=>f.id),rejectedIds:[],decision:'accepted',missing:[],notes:'Kaynak kapsamı ve birimler korunarak denetlendi.',nextTask:next,repairTask:{instruction:'Eksik pazar bilgisini doğru markanın kaynaklarından yeniden doğrula.',queries:['Acme Organic target market Türkiye']},...(stage.includes('competition')?{peers:plan.entities.filter(e=>e.role==='competitor').map(e=>({entityId:e.id,relationship:'direct',sourceIds:[section(input,new RegExp(e.name+" Türkiye'de")).id],reason:'Aynı organik atıştırmalık ürünü, tüketici ihtiyacı ve Türkiye pazarı.'}))}:{})};
 }
 if(stage==='v8-coverage-plan')return {coverage:Object.fromEntries(methodologyAreas.map(a=>[a.key,{status:'partial',findingIds:[],note:'Alan kapsamı final kaynak denetiminde tamamlanacak.'}])),queries:['Acme Organic customer support response'],actorRequests:[],priorities:['Yorumların ve yanıtların kapsamını doğrula.']};
 if(stage==='v8-gap-extract')return {facts:[fact(input,'correction1','customer_behavior',/müşterileri içerik açıklaması/)],unknowns:['Özel kâr ve dönüşüm verisi bulunmadı.']};
 if(stage==='v8-final-report'||stage==='v8-report-draft'){
  const specs=[['financial',/listelenen fiyatı/,'strength'],['financial',/sektöründe gelir/,'opportunity'],['operations',/teslimat süresi/,'strength'],['operations',/şirketine bağlıdır/,'strength'],['funnel',/e-posta bültenine/,'strength'],['funnel',/doğrudan tüketiciye/,'strength'],['digital',/Statik HTML/,'strength'],['digital',/Organic Alpha için/,'opportunity'],['perception',/teslimat gecikmesini/,'weakness'],['perception',/müşterileri içerik açıklaması/,'opportunity'],['competition',/Organic Beta Türkiye/,'strength'],['competition',/hammadde maliyetleri/,'threat'],['competition',/Organic Gamma Türkiye/,'strength']];
  const raw=specs.map((s,i)=>finding(input,'f'+i,...s)),findings=raw.map(({quadrant,...f})=>f);
  return {findings,peers:input.peerReview,dimensions:dimensions.map(d=>({id:d.id,score:null,findingIds:findings.filter(f=>f.dimension===d.id).map(f=>f.id),comparisonFindingIds:['f10','f12'],bandReason:'Kapsamlı puan için iç veriler görüşmede doğrulanacak.'})),coverage:Object.fromEntries(methodologyAreas.map(a=>[a.key,{status:'partial',findingIds:findings.filter(f=>f.dimension===a.dimension).map(f=>f.id),note:'Kaynaklı kamu sinyalleri; özel metrikler görüşmede doğrulanacak.'}])),benchmarks:[],overviewIds:['f0','f2','f8'],opportunityId:'f1',riskId:'f11',swot:Object.fromEntries(['strength','weakness','opportunity','threat'].map(q=>[q,raw.filter(f=>f.quadrant===q).map(f=>f.id)]))};
 }
 throw Error('Unexpected fixture stage '+stage);
}
